        while j < n and text[j] != "=" and text[j] != SEP:
            j += 1
        if j == n or text[j] == SEP:
            field = text[i:j]
            if field.strip():
                raise ValueError(f"field without '=': {field!r}")
            i = j + 1
            continue
        key = text[i:j].strip()
        if not key:
            raise ValueError(f"empty key in {text[i:j + 1]!r}")
        i = j + 1
        while i < n and text[i].isspace() and text[i] != SEP and text[i] != QUOTE:
            i += 1
        if i < n and text[i] == QUOTE:
            i += 1
            chars = []
            while True:
                if i >= n:
                    raise ValueError(f"unclosed quote in value of {key!r}")
                if text[i] == QUOTE:
                    if i + 1 < n and text[i + 1] == QUOTE:
                        chars.append(QUOTE)
                        i += 2
                        continue
                    i += 1
                    break
                chars.append(text[i])
                i += 1
            value = "".join(chars)
            j = i
            while j < n and text[j] != SEP:
                j += 1
            if text[i:j].strip():
                raise ValueError(f"text after closing quote in value of {key!r}")
        else:
            j = i
            while j < n and text[j] != SEP:
                j += 1
            value = text[i:j].strip()
        i = j + 1
        if key in result:
            raise ValueError(f"duplicate key: {key!r}")
        result[key] = value
    return result
